'use strict';
const $=id=>document.getElementById(id), I=Inventory;
const keys=['search','location','batch','customer','status','sample','start','end',...(window.Connected?['contract_no','weight_basis','business_status']:[])];
let page=1,size=10,sort='date',direction='desc',filtered=[],selected=new Set(),toastTimer;
const logs=[];
const remote=!!window.Connected;
let totalRows=0,requestSequence=0,serviceReady=!remote,filterSignature='';
const canExport=()=>remote?CurrentUser.permissions.includes('inventory:export'):$('role').value==='manager';
const filterValues=()=>Object.fromEntries(keys.map(k=>[k,$(k).value]));
function serviceError(error){serviceReady=false;selected.clear();$('metrics').replaceChildren();$('rows').innerHTML=`<tr><td colspan="${remote?16:10}" class="empty"><strong>数据库查询失败</strong>${esc(error.message)}</td></tr>`;$('result-count').textContent='不可用';$('page-summary').textContent='数据不可用，未使用演示数据替代';$('csv').disabled=true;$('excel').disabled=true;notify(error.message);}
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
function notify(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,4500);}
function audit(action){logs.unshift({time:new Date().toLocaleString('zh-CN'),role:$('role').selectedOptions[0].textContent,action});if(logs.length>50)logs.pop();}
function dialog(title,html){$('dialog').classList.remove('business-dialog');$('dialog-title').textContent=title;$('dialog-content').innerHTML=html;$('dialog').showModal();}
function format(n){return Tonnes.format(n,true);}
async function populateOptions(){const options=remote?await API.request('/inventory/options'):Object.fromEntries(['location','batch','customer'].map(k=>[k,[...new Set(I.data.map(r=>r[k]))].sort()]));for(const k of (remote?['location','batch','customer','allocated_customer']:['location','batch','customer'])){const previous=$(k).value;$(k).replaceChildren($(k).options[0].cloneNode(true));for(const value of [...new Set([...options[k],...(previous?[previous]:[])])]){const o=document.createElement('option');o.value=value;o.textContent=value;$(k).append(o);}$(k).value=previous;}}
function updateMetrics(t=I.totals(filtered)){const cards=[['在库净重',format(t.weight),'吨','▤',`仅在库 + 已预留`],['可用捆包',t.available,'捆','▦',`已预留 <b>${t.reserved}</b> 捆 · 不计入可用`],['待完成取样',t.pending,'捆','◈','在库范围 · 未取样 + 取样中'],['匹配捆包',t.count,'捆','≡',`其中已出库 <b>${t.outbound}</b> 捆`]];if(remote){cards.push(['库存总片数',t.total_sheets??'未录入','片','▦',t.missing_sheets_count?'另有 '+t.missing_sheets_count+' 捆未录入':'当前库存范围']);cards[0][0]='现场已知净重';cards[0][1]=format(t.physical_weight);cards[0][4]='未检斤 '+(t.unweighed_count||0)+' 捆；未知重量不汇总';cards.splice(1,0,['有效锁定净重',format(t.locked_weight),'吨','▣','整捆锁定 · 不减少实物'],['可用库存净重',format(t.available_weight),'吨','▤','实物库存 − 有效锁定']);}$('metrics').innerHTML=cards.map(c=>`<article class="metric"><div class="metric-top"><span>${c[0]}</span><span class="metric-icon" aria-hidden="true">${c[3]}</span></div><div class="metric-value">${c[1]}<small>${c[2]}</small></div><div class="metric-bottom">${c[4]}</div></article>`).join('');}
async function render(){
  const sequence=++requestSequence;
  const f=Object.fromEntries(keys.map(k=>[k,$(k).value]));const invalid=f.start&&f.end&&f.start>f.end;
  $('date-error').hidden=!invalid; $('start').setAttribute('aria-invalid',!!invalid);$('end').setAttribute('aria-invalid',!!invalid);
  let metrics,part;
  if(remote){
    if(invalid){serviceError(Error('开始日期不能晚于结束日期'));return;}
    $('csv').disabled=true;$('excel').disabled=true;
    try{
      const signature=JSON.stringify(f);let validSelection;
      if(signature!==filterSignature&&selected.size)validSelection=(await API.request('/inventory/selection',{method:'POST',body:{filters:f,selected_ids:[...selected]}})).ids;
      const result=await API.request('/inventory?'+new URLSearchParams({...f,sort,direction,page,page_size:size}));
      if(sequence!==requestSequence)return;
      if(validSelection)selected=new Set(validSelection);filterSignature=signature;
      filtered=result.items;part=filtered;page=result.page;totalRows=result.total;metrics=result.summary;serviceReady=true;
    }catch(error){if(sequence===requestSequence)serviceError(error);return;}
  }else{filtered=I.query(I.data,f,sort,direction);totalRows=filtered.length;const ids=new Set(filtered.map(r=>r.id));selected=new Set([...selected].filter(id=>ids.has(id)));page=Math.min(page,Math.max(1,Math.ceil(totalRows/size)));part=filtered.slice((page-1)*size,page*size);}
  const pages=Math.max(1,Math.ceil(totalRows/size));
  updateMetrics(metrics);$('result-count').textContent=totalRows+' 捆';$('table-subtitle').textContent='当前筛选结果 · 捆包级明细 · 净重单位：吨';
  const active=keys.filter(k=>f[k]).length;$('filter-summary').textContent=active?`已应用 ${active} 项筛选 · 日期按入库日期（含首尾）`:'筛选条件实时生效 · 日期按入库日期（含首尾）';
  $('rows').innerHTML=part.length?part.map(r=>`<tr class="${selected.has(r.id)?'selected':''}"><td class="check-cell"><input type="checkbox" data-id="${esc(r.id)}" aria-label="选择 ${esc(r.id)}" ${selected.has(r.id)?'checked':''}></td><td class="bundle">${esc(r.id)}</td><td>${esc(r.batch)}</td><td>${remote?`<a class="location-chip" href="/stock-map?${esc(new URLSearchParams({project_id:r.project_id,warehouse_id:r.warehouse_id,location_code:r.location}).toString())}" title="在库存地图定位货位">${esc(r.location)}</a>`:`<span class="location-chip">${esc(r.location)}</span>`}</td><td>${r.sheets_per_bundle??'未录入'}</td><td>${esc(r.seal_no?(r.seal_no+(r.seal_valid===false?'（待确认）':'')):'未录入')}</td><td class="database-column numeric">${r.weight===null?'待检斤':esc(r.gross_weight?Tonnes.format(r.gross_weight):'历史未知')}</td><td class="database-column numeric">${esc(Tonnes.format(r.packaging_weight))}</td><td class="numeric" title="${esc(r.weight)} 吨（完整精度）">${format(r.weight)}</td><td class="database-column">${esc((r.weight===null?{LEGACY_NET_ONLY:'未检斤'}:{LEGACY_NET_ONLY:'历史毛重未知',AUTHORIZED_ADJUSTED_NET:'授权调整后的净重',GROSS_MINUS_PACKAGING:'毛重扣包'})[r.weight_basis]||'—')}</td><td><span class="badge ${r.status==='在库'?'green':r.status==='已预留'?'amber':'gray'}">${esc(r.business_status||r.status)}</span></td><td><span class="sample ${r.sample==='已取样'?'done':r.sample==='取样中'?'working':'wait'}">${r.sample==='已取样'?'✓ ':r.sample==='取样中'?'◷ ':'○ '}${r.sample}</span></td><td>${esc(r.date)}</td><td class="database-column">${esc(r.current_customer||r.allocated_customer||r.customer)}</td><td class="database-column">${esc(r.lot_no||'—')}</td><td class="database-column">${esc(r.planned_location||'—')}</td><td class="database-column">${r.sample_required?'取样 · '+esc(typeof V261!=='undefined'?V261.sampleStates[r.lot_sample_stage]||r.lot_sample_stage:r.lot_sample_stage):'无需取样'}</td><td class="database-column">${r.final_weighed===false||r.weight===null?'待检斤':'已知重量'}</td><td class="database-column">${esc(r.receipt_code||'期初快照')}</td><td class="database-column">${esc(r.confirmed_at?new Date(r.confirmed_at).toLocaleString('zh-CN'):'未知')}</td><td><button class="detail-button" data-detail="${esc(r.id)}">详情</button></td></tr>`).join(''):`<tr><td colspan="${remote?16:10}" class="empty"><strong>${invalid?'请检查日期范围':'没有匹配的捆包'}</strong>${invalid?'开始日期应早于或等于结束日期。':'请尝试其他搜索条件，或点击“重置筛选”。'}</td></tr>`;
  $('page-summary').textContent=totalRows?`共 ${totalRows} 条 · 第 ${(page-1)*size+1}–${Math.min(page*size,totalRows)} 条`:'共 0 条记录';
  $('previous').disabled=page<=1;$('next').disabled=page>=pages;
  const visible=[...new Set([1,page-1,page,page+1,pages])].filter(n=>n>=1&&n<=pages).sort((a,b)=>a-b);let last=0;
  $('page-buttons').innerHTML=visible.map(n=>{const gap=n-last>1?'<span class="ellipsis">…</span>':'';last=n;return gap+`<button class="page-button ${n===page?'active':''}" data-page="${n}" aria-label="第 ${n} 页" ${n===page?'aria-current="page"':''}>${n}</button>`;}).join('');
  const checked=part.filter(r=>selected.has(r.id)).length;$('select-page').checked=part.length>0&&checked===part.length;$('select-page').indeterminate=checked>0&&checked<part.length;$('select-page').disabled=!part.length;
  $('selection-count').textContent=selected.size?`已选 ${selected.size} 捆`:'全部筛选结果';
  const allowed=canExport();for(const id of ['csv','excel']){$(id).disabled=!allowed||!totalRows;$(id).title=!allowed?(remote?'服务端未授予导出权限':'只读访客没有导出权限（前端演示）'):!totalRows?'暂无可导出的记录':selected.size?'导出当前筛选中所有已选捆包':'导出全部筛选结果，包含所有分页';}
  $('export-note').textContent=allowed?(selected.size?'仅导出已选捆包':'管理员可导出 · 全部筛选结果'):(remote?'当前账号无导出权限':'只读访客 · 无导出权限（演示）');
  document.querySelectorAll('th[data-sort]').forEach(th=>{th.removeAttribute('aria-sort');th.querySelector('span').textContent='↕';if(th.dataset.sort===sort){th.setAttribute('aria-sort',direction==='asc'?'ascending':'descending');th.querySelector('span').textContent=direction==='asc'?'↑':'↓';}});
}
function apply(){page=1;render();}
let searchTimer;keys.forEach(k=>$(k).addEventListener(k==='search'?'input':'change',()=>{clearTimeout(searchTimer);if(remote&&k==='search')searchTimer=setTimeout(apply,200);else apply();}));
$('filter-form').addEventListener('submit',async e=>{e.preventDefault();page=1;await render();if(remote&&!serviceReady)return;if(!$('date-error').hidden){notify('日期范围无效，请先调整日期。');return;}audit(`查询库存：${totalRows} 捆`);notify(`查询完成，共找到 ${totalRows} 捆${remote?'数据库':'演示'}库存。`);});
$('reset').onclick=()=>{keys.forEach(k=>$(k).value='');selected.clear();page=1;render();notify('已重置全部筛选条件。');};
$('page-size').onchange=()=>{size=Number($('page-size').value);page=1;render();};
$('previous').onclick=()=>{if(page>1){page--;render();}};$('next').onclick=()=>{if(page<Math.ceil(totalRows/size)){page++;render();}};
$('page-buttons').onclick=e=>{const b=e.target.closest('[data-page]');if(b){page=Number(b.dataset.page);render();}};
document.querySelectorAll('th[data-sort] button').forEach(b=>b.onclick=()=>{const k=b.parentElement.dataset.sort;direction=sort===k&&direction==='asc'?'desc':'asc';sort=k;page=1;render();});
$('select-page').onchange=()=>{const on=$('select-page').checked;(remote?filtered:filtered.slice((page-1)*size,page*size)).forEach(r=>on?selected.add(r.id):selected.delete(r.id));render();};
$('rows').onchange=e=>{if(e.target.dataset.id){e.target.checked?selected.add(e.target.dataset.id):selected.delete(e.target.dataset.id);render();}};
$('rows').onclick=async e=>{try{const id=e.target.closest('[data-detail]')?.dataset.detail;if(!id)return;const r=remote?await API.request('/bundles/'+encodeURIComponent(id)):I.data.find(r=>r.id===id);audit(`查看捆包：${id}`);dialog('捆包详情',`<p class="dialog-notice">${remote?(AppConfig.environment==='test'?'隔离测试数据库记录 · 不可用于业务结算':'授权数据库记录'):'演示记录 · 本页所有数据均为虚构，不可用于业务结算。'}</p><dl>${[['捆包编号',r.id],['生产批次',r.batch],['货位',r.location],['当前分配客户',r.current_customer||r.customer],['净重',(remote?r.weight:format(r.weight))+' 吨'],['库存状态',r.status],['取样状态',r.sample],['入库日期',r.date],['产品等级',r.grade],['铜含量',r.purity]].map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl><p>日期为仓库业务日期；V2.1 仅提供查询与导出，不开放库存变更。</p>`);}catch(error){notify(error.message);}};
$('role').onchange=()=>{selected.clear();render();audit('切换演示角色');notify($('role').value==='viewer'?'已切换至只读访客：可查询、查看详情，不能导出。':'已切换至库存管理员：可查询和导出。');};
async function download(kind){if(remote){if(!canExport()||!serviceReady)return;try{const result=await API.request('/inventory/exports',{method:'POST',binary:true,body:{format:kind,filters:filterValues(),sort:{sort,direction},selected_ids:[...selected]}});const url=URL.createObjectURL(result.blob),a=document.createElement('a');a.href=url;a.download='穆松尼_'+AppConfig.environment+'_'+result.count+'捆.'+kind;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);notify('已生成 '+result.count+' 捆的授权导出文件。');}catch(error){notify(error.message);}return;}if($('role').value!=='manager'){notify('当前角色无导出权限（演示）。');return;}if(!filtered.length){notify('没有可导出的记录。');return;}const rows=selected.size?filtered.filter(r=>selected.has(r.id)):filtered;try{const blob=new Blob([kind==='csv'?I.csv(rows):I.xlsx(rows)],{type:kind==='csv'?'text/csv;charset=utf-8':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`穆松尼_库存演示_${selected.size?'已选':'筛选结果'}_${rows.length}捆_${new Date().toISOString().slice(0,10)}.${kind}`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);audit(`导出 ${kind.toUpperCase()}：${rows.length} 捆（演示数据）`);notify(`已生成 ${rows.length} 捆的 ${kind.toUpperCase()} 演示文件，请查看浏览器下载。`);}catch(error){console.error(error);notify('导出失败，请稍后重试。');}}
$('csv').onclick=()=>download('csv');$('excel').onclick=()=>download('xlsx');
$('close-dialog').onclick=()=>$('dialog').close();$('dialog').onclick=e=>{if(e.target===$('dialog')){const r=$('dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('dialog').close();}};
document.querySelectorAll('[data-info]').forEach(b=>b.onclick=()=>dialog(b.dataset.info+' · 功能范围',`<p>本次原型实现库存查询与导出。${esc(b.dataset.info)}列为后续模块，尚未实现。</p><p>后续接入数据库时，可在此建立相应的业务单据与审批流程。</p>`));
$('audit-nav').onclick=async()=>{if(remote){try{const r=await API.request('/audit');dialog('服务端操作日志','<p>最近 100 条授权日志，时间由服务端记录。</p><ol>'+r.items.map(l=>'<li>'+esc(l.occurred_at)+' · '+esc(l.username||'系统')+' · '+esc(l.action)+'<br>'+esc(JSON.stringify(l.after_data||{}))+'</li>').join('')+'</ol>');}catch(error){notify(error.message);}return;}dialog('演示操作记录',`<p class="dialog-notice">仅保存在当前页面内存，刷新后清空。正式审计日志需由服务端持久化。</p>${logs.length?'<ol>'+logs.map(l=>`<li>${esc(l.time)} · ${esc(l.role)}<br>${esc(l.action)}</li>`).join('')+'</ol>':'<p>暂无操作记录。</p>'}`);};
$('guide').onclick=()=>{if(remote){dialog('V2.2 数据库模式说明','<p>当前为 '+esc(AppConfig.environment)+' 环境，数据来自 PostgreSQL。角色和数据范围由服务端验证；没有模拟数据回退。</p><p>保留搜索、筛选、排序、分页、跨页勾选和导出。未勾选时导出全部筛选结果；有勾选时只导出选中记录；筛选改变后移除不再匹配的勾选。单次导出上限 10000 条。悬停重量可查看完整精度，导出统一四位小数，数据库保留历史原始精度。</p><p>业务入口提供基础资料、入库草稿/审核、Excel导入、销售计划与整捆锁定。暂不开放取样、装车、出库和冲销。演示回归入口为 /demo，独立于数据库模式。</p>');return;}dialog('使用说明与权限',`<p class="dialog-notice">128 条确定性演示数据 · 快照日期 2026-10-28 · 未连接数据库</p><ol><li>输入捆包号、批次、客户或货位，组合筛选实时生效；日期按入库日期，包含开始及结束日。</li><li>点击列标题切换升序/降序；在表格底部翻页或调整每页条数。</li><li>指标按全部筛选结果计算。在库净重 = 在库 + 已预留；可用捆包仅指“在库”；待完成取样仅统计仍在库的未取样与取样中捆包。</li><li>未勾选时导出全部筛选结果；勾选后仅导出已选捆包，可跨页选择。改变筛选后自动移除不再匹配的已选项。CSV 使用 UTF-8 BOM；Excel 为真正的 .xlsx 格式，重量为数值。</li><li>顶部可切换演示角色。只读访客可查询和查看详情；管理员可导出。这是前端交互演示，不能替代服务端鉴权。</li><li>筛选、角色和操作记录不持久化，刷新会重置。入库、出库与取样业务办理不在本原型范围。</li></ol><p>后续方案：HTTPS API + PostgreSQL，服务端统一处理权限、筛选、统计、导出及审计。详细接口和数据结构见交付文件 README.md。</p>`);};
if(remote){$('users-nav').hidden=!CurrentUser.permissions.includes('users:manage');$('users-nav').onclick=()=>manageUsers().catch(e=>notify(e.message));}
populateOptions().then(render).catch(serviceError);

if(remote)window.addEventListener('inventory-changed',()=>populateOptions().then(render).catch(serviceError));
